'use strict';

/**
 * Session and user checks shared by every authenticated route.
 * Sessions live in process.env.SESSIONS_TABLE keyed by the SHA-256 hex of the bearer token.
 * Users live in process.env.USERS_TABLE keyed by email, with GSI byUserId (PK userId).
 */

const crypto = require('crypto');
const { GetCommand, QueryCommand } = require('@aws-sdk/lib-dynamodb');
const { doc } = require('../database');
const { unauthorized, forbidden } = require('../errors');

const USERS_BY_USER_ID = 'byUserId';
const TEMPORARY = 'TEMPORARY';

const BEARER = /^Bearer\s+(\S+)\s*$/i;

function hashToken(token) {
    return crypto.createHash('sha256').update(token, 'utf8').digest('hex');
}

/** Returns the raw bearer token from the Authorization header (any case), or null. */
function readBearerToken(event) {
    const headers = (event && event.headers) || {};
    let value;
    for (const name of Object.keys(headers)) {
        if (name.toLowerCase() === 'authorization') {
            value = headers[name];
            break;
        }
    }
    if (typeof value !== 'string') return null;
    const m = BEARER.exec(value.trim());
    if (!m || m[1].length > 200) return null;
    return m[1];
}

/**
 * Validates the bearer token. Returns { userId, email, name, expiresAt, tokenHash }
 * or throws 401 UNAUTHORIZED.
 */
async function requireSession(event) {
    const token = readBearerToken(event);
    if (!token) throw unauthorized();
    const tokenHash = hashToken(token);
    const res = await doc.send(new GetCommand({ TableName: process.env.SESSIONS_TABLE, Key: { tokenHash } }));
    const item = res.Item;
    if (!item || !item.expiresAt || Date.parse(item.expiresAt) <= Date.now()) throw unauthorized();
    return { userId: item.userId, email: item.email, name: item.name, expiresAt: item.expiresAt, tokenHash };
}

/** Users written before FR1 have no isAdmin and are admins. Only an explicit false is a member. */
function effectiveIsAdmin(item) {
    return item.isAdmin !== false;
}

/** True while the user holds a temporary password (expired or not). */
function hasTemporaryPassword(item) {
    return item.passwordState === TEMPORARY;
}

function toUser(item) {
    const temporary = hasTemporaryPassword(item);
    return {
        userId: item.userId,
        email: item.email,
        name: item.name,
        isAdmin: effectiveIsAdmin(item),
        workerId: item.workerId || null,
        mustChangePassword: temporary,
        tempPasswordExpiresAt: temporary ? item.tempPasswordExpiresAt || null : null,
    };
}

async function getUserByEmail(email) {
    const res = await doc.send(
        new GetCommand({ TableName: process.env.USERS_TABLE, Key: { email }, ConsistentRead: true })
    );
    return res.Item || null;
}

/**
 * Loads the current Users item of a session. Reads by the session's email (consistent); if that item
 * is missing or belongs to another userId (email changed or reused), looks the user up by userId on
 * the byUserId GSI and re-reads each candidate by its email so a stale index entry is never trusted.
 * Returns the user object, or throws 401 UNAUTHORIZED when the user no longer exists.
 */
async function loadUserForSession(session) {
    let item = session.email ? await getUserByEmail(session.email) : null;
    if (!item || item.userId !== session.userId) {
        item = null;
        const res = await doc.send(
            new QueryCommand({
                TableName: process.env.USERS_TABLE,
                IndexName: USERS_BY_USER_ID,
                KeyConditionExpression: 'userId = :id',
                ExpressionAttributeValues: { ':id': session.userId },
                ProjectionExpression: 'email',
            })
        );
        for (const candidate of res.Items || []) {
            const current = await getUserByEmail(candidate.email);
            if (current && current.userId === session.userId) {
                item = current;
                break;
            }
        }
    }
    if (!item) throw unauthorized();
    return toUser(item);
}

/**
 * Temporary-password gate. Expired temporary password: 401 UNAUTHORIZED. Active temporary password:
 * 403 PASSWORD_CHANGE_REQUIRED unless the route allows it (me, password, logout).
 */
function assertUserAllowed(user, { allowTemporaryPassword = false } = {}) {
    if (!user.mustChangePassword) return;
    const expiresAt = user.tempPasswordExpiresAt ? Date.parse(user.tempPasswordExpiresAt) : NaN;
    if (!(expiresAt > Date.now())) throw unauthorized();
    if (!allowTemporaryPassword) throw forbidden('PASSWORD_CHANGE_REQUIRED', 'Set a new password to continue');
}

/**
 * Session -> current user record -> temporary-password gate. Returns
 * { userId, email, name, isAdmin, workerId, mustChangePassword, tempPasswordExpiresAt }.
 */
async function requireUser(event, options = {}) {
    const session = await requireSession(event);
    const user = await loadUserForSession(session);
    assertUserAllowed(user, options);
    return user;
}

module.exports = {
    hashToken,
    readBearerToken,
    requireSession,
    requireUser,
    loadUserForSession,
    assertUserAllowed,
    effectiveIsAdmin,
    hasTemporaryPassword,
    toUser,
};
